// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  BookmarkPlusIcon,
  CodeXmlIcon,
  ContrastIcon,
  LayersIcon,
  LayoutTemplateIcon,
  LibraryBigIcon,
  LockIcon,
  PlusIcon,
  Redo2Icon,
  ShuffleIcon,
  SlidersHorizontalIcon,
  Undo2Icon,
  UnlockIcon,
} from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  CONTRAST,
  EXPORT,
  HARMONIES,
  HARMONY_INDEX,
  LOCKED,
  REGENERATED,
  ROLE_LABELS,
  SCALE,
  START,
  TRIADIC,
  colorName,
  formatValues,
  textOn,
} from './script'

const SECTIONS = [
  { id: 'inspect', label: 'Inspect', icon: SlidersHorizontalIcon },
  { id: 'scales', label: 'Scales', icon: LayersIcon },
  { id: 'contrast', label: 'Contrast', icon: ContrastIcon },
  { id: 'preview', label: 'Preview', icon: LayoutTemplateIcon },
  { id: 'export', label: 'Export', icon: CodeXmlIcon },
  { id: 'library', label: 'Library', icon: LibraryBigIcon },
]
const FORMATS = [
  'CSS variables',
  'Tailwind v4',
  'Tailwind v3',
  'SCSS',
  'JSON',
  'Design tokens',
  'SVG',
]
const SHARE = CONTRAST.passing / CONTRAST.total
const RING = 2 * Math.PI * 13

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const inspect = (hex: string, at: number | string) => {
    tl.set(q('inspect-name'), { text: `${ROLE_LABELS[0]} · ${colorName(hex)}` }, at)
    formatValues(hex).forEach(({ value }, index) =>
      tl.set(q(`inspect-${index}`), { text: value }, at),
    )
  }
  const paint = (hexes: string[], columns: number[], at: string) => {
    if (columns.includes(0)) inspect(hexes[0], at)
    columns.forEach((index, order) => {
      const hex = hexes[index]
      const position = order === 0 ? at : '<0.05'
      tl.to(
        q(`col-${index}`),
        { backgroundColor: hex, color: textOn(hex), duration: 0.45, ease: 'power2.inOut' },
        position,
      )
      tl.set(q(`name-${index}`), { text: colorName(hex) }, '<0.2')
      tl.set(q(`hex-${index}`), { text: hex.toUpperCase() }, '<')
    })
  }
  const section = (id: string) => {
    move(`sec-${id}`)
    click(`sec-${id}`)
    tl.to(
      qa('sec'),
      { backgroundColor: 'rgba(255,255,255,0)', color: '#8b8b96', duration: 0.15 },
      '<',
    )
    tl.to(
      q(`sec-${id}`),
      { backgroundColor: 'rgba(255,255,255,0.1)', color: '#f4f4f5', duration: 0.15 },
      '<',
    )
    tl.to(qa('view'), { opacity: 0, duration: 0.15 }, '<')
    tl.fromTo(
      q(`view-${id}`),
      { opacity: 0, y: 6 },
      { opacity: 1, y: 0, duration: 0.25, immediateRender: false },
      '>',
    )
  }

  step(0)
  move(`harmony-${HARMONY_INDEX}`, { at: 0.4 })
  click(`harmony-${HARMONY_INDEX}`)
  tl.set(qa('harmony'), { backgroundColor: 'transparent', color: '#8b8b96' }, '<')
  tl.set(q(`harmony-${HARMONY_INDEX}`), { backgroundColor: 'var(--accent)', color: '#0b0b10' }, '<')
  paint(
    TRIADIC,
    TRIADIC.map((_, index) => index),
    '<0.1',
  )
  wait(0.6)

  step(1, '+=0.1')
  LOCKED.forEach((index) => {
    move(`lock-${index}`)
    click(`lock-${index}`)
    tl.to(q(`unlocked-${index}`), { opacity: 0, duration: 0.12 }, '<')
    tl.to(q(`locked-${index}`), { opacity: 1, duration: 0.12 }, '<')
  })
  move('generate', { at: '+=0.1' })
  tl.fromTo(
    q('space'),
    { opacity: 0, y: 8, scale: 0.9 },
    { opacity: 1, y: 0, scale: 1, duration: 0.2, immediateRender: false },
    '>',
  )
  tl.to(q('space'), { scale: 0.92, duration: 0.08, yoyo: true, repeat: 1 }, '>')
  const unlocked = REGENERATED.map((_, index) => index).filter((index) => !LOCKED.includes(index))
  paint(REGENERATED, unlocked, '<')
  tl.to(q('space'), { opacity: 0, duration: 0.2 }, '+=0.4')

  step(2, '+=0.2')
  section('scales')
  tl.fromTo(
    qa('scale-step'),
    { opacity: 0, scaleY: 0.4 },
    { opacity: 1, scaleY: 1, duration: 0.25, stagger: 0.03, immediateRender: false },
    '<',
  )
  wait(0.6)
  section('contrast')
  tl.fromTo(
    q('ring'),
    { strokeDashoffset: RING },
    {
      strokeDashoffset: RING * (1 - SHARE),
      duration: 0.6,
      ease: 'power2.out',
      immediateRender: false,
    },
    '<',
  )
  wait(0.6)

  step(3, '+=0.1')
  section('export')
  EXPORT.forEach((line, index) =>
    type(`code-${index}`, line, { at: index === 0 ? '<0.1' : '>', speed: 0.01 }),
  )
  cursorOut('+=0.4')
  final('+=0.1')
  wait(1.4)

  inspect(START[0], 0)
  START.forEach((hex, index) => {
    tl.set(q(`col-${index}`), { backgroundColor: hex, color: textOn(hex) }, 0)
    tl.set(q(`name-${index}`), { text: colorName(hex) }, 0)
    tl.set(q(`hex-${index}`), { text: hex.toUpperCase() }, 0)
  })
  tl.set(qa('harmony'), { backgroundColor: 'transparent', color: '#8b8b96' }, 0)
  tl.set(q('harmony-0'), { backgroundColor: 'var(--accent)', color: '#0b0b10' }, 0)
  tl.set(qa('sec'), { backgroundColor: 'rgba(255,255,255,0)', color: '#8b8b96' }, 0)
  tl.set(q('sec-inspect'), { backgroundColor: 'rgba(255,255,255,0.1)', color: '#f4f4f5' }, 0)
  tl.set(qa('view'), { opacity: 0 }, 0)
  tl.set(q('view-inspect'), { opacity: 1, y: 0 }, 0)
  tl.set([...qa('locked'), q('space')], { opacity: 0 }, 0)
  tl.set(qa('unlocked'), { opacity: 1 }, 0)
}

function Stage() {
  return (
    <div className="overflow-hidden rounded-lg border border-line">
      <div className="flex h-[78px]">
        {START.map((hex, index) => (
          <div
            key={index}
            data-d={`col-${index}`}
            className="flex flex-1 flex-col justify-between p-1.5"
            style={{ backgroundColor: hex, color: textOn(hex) }}
          >
            <span className="text-[7px] font-medium uppercase tracking-wide opacity-70">
              {ROLE_LABELS[index]}
            </span>
            <span>
              <span data-d={`name-${index}`} className="block truncate text-[8.5px] font-semibold">
                {colorName(hex)}
              </span>
              <span data-d={`hex-${index}`} className="block font-mono text-[8px] opacity-80">
                {hex.toUpperCase()}
              </span>
            </span>
            <span data-d={`lock-${index}`} className="grid w-fit [&>*]:[grid-area:1/1]">
              <UnlockIcon data-d={`unlocked unlocked-${index}`} className="size-2.5 opacity-70" />
              <LockIcon data-d={`locked locked-${index}`} className="size-2.5 opacity-0" />
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}

function Views() {
  return (
    <div className="relative min-h-0 flex-1">
      <div data-d="view view-inspect" className="absolute inset-0">
        <p data-d="inspect-name" className="mb-1 text-[7.5px] text-muted">
          {ROLE_LABELS[0]} · {colorName(START[0])}
        </p>
        <div className="grid grid-cols-2 gap-1 text-[7.5px]">
          {formatValues(START[0]).map(({ label, value }, index) => (
            <span
              key={label}
              className="flex justify-between gap-2 rounded border border-line px-1.5 py-0.5"
            >
              <span className="text-muted">{label}</span>
              <span data-d={`inspect-${index}`} className="truncate font-mono text-ink">
                {value}
              </span>
            </span>
          ))}
        </div>
      </div>
      <div data-d="view view-scales" className="absolute inset-0 opacity-0">
        <p className="mb-1 text-[7.5px] text-muted">
          {ROLE_LABELS[0]} · perceptual OKLCH ramp, the dot marks your colour
        </p>
        <div className="flex h-9 gap-0.5">
          {SCALE.map((entry) => (
            <span
              key={entry.step}
              data-d="scale-step"
              className="relative flex flex-1 items-end justify-center rounded-sm pb-0.5 text-[6.5px]"
              style={{ backgroundColor: entry.hex, color: textOn(entry.hex) }}
            >
              {entry.step}
              {entry.isBase ? (
                <span
                  className="absolute top-1 size-1 rounded-full"
                  style={{ backgroundColor: textOn(entry.hex) }}
                />
              ) : null}
            </span>
          ))}
        </div>
      </div>
      <div
        data-d="view view-contrast"
        className="absolute inset-0 flex items-center gap-2 opacity-0"
      >
        <svg viewBox="0 0 32 32" className="size-9 -rotate-90">
          <circle
            cx="16"
            cy="16"
            r="13"
            fill="none"
            stroke="rgba(255,255,255,0.1)"
            strokeWidth="3"
          />
          <circle
            data-d="ring"
            cx="16"
            cy="16"
            r="13"
            fill="none"
            stroke="#10b981"
            strokeWidth="3"
            strokeLinecap="round"
            strokeDasharray={RING}
            strokeDashoffset={RING}
          />
        </svg>
        <span>
          <span className="block text-[9px] font-semibold text-ink">
            {CONTRAST.passing} of {CONTRAST.total} text and background pairs pass AA.
          </span>
          <span className="block text-[7.5px] text-muted">
            Normal text, 4.5:1 · each colour, white and black on every background
          </span>
        </span>
      </div>
      <div data-d="view view-export" className="absolute inset-0 flex gap-2 opacity-0">
        <div className="flex w-20 shrink-0 flex-col gap-0.5">
          {FORMATS.map((format) => (
            <span
              key={format}
              className={`rounded px-1 py-px text-[7px] ${format === 'Tailwind v4' ? 'bg-white/10 text-ink' : 'text-muted'}`}
            >
              {format}
            </span>
          ))}
        </div>
        <div className="min-w-0 flex-1 rounded border border-line bg-canvas/60 p-1.5 font-mono text-[7.5px] leading-[11px] text-ink">
          {EXPORT.map((_, index) => (
            <p key={index} data-d={`code-${index}`} className="h-[11px] whitespace-pre" />
          ))}
        </div>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Palette Generator turning one blue into a triadic palette, locking one colour, regenerating the rest, checking scales and contrast, and exporting Tailwind v4 variables`}
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="relative flex h-full flex-col gap-1.5">
          <div className="flex items-center gap-1 text-[8px]">
            <span
              data-d="generate"
              className="flex items-center gap-1 rounded-md bg-[var(--accent)] px-1.5 py-0.5 font-semibold text-canvas"
            >
              <ShuffleIcon className="size-2.5" /> Generate
              <span className="rounded bg-black/20 px-1 text-[6.5px]">Space</span>
            </span>
            <Undo2Icon className="ml-1 size-3 text-muted" />
            <Redo2Icon className="size-3 text-muted" />
            <span className="ml-auto flex items-center gap-1 text-muted">
              <PlusIcon className="size-3" />
              <BookmarkPlusIcon className="size-3" /> Save
            </span>
          </div>
          <Stage />
          <div className="flex gap-0.5">
            {HARMONIES.map((harmony, index) => (
              <span
                key={harmony.id}
                data-d={`harmony harmony-${index}`}
                className="flex-1 rounded px-1 py-0.5 text-center text-[7px]"
                style={
                  index === 0
                    ? { backgroundColor: 'var(--accent)', color: '#0b0b10' }
                    : { color: '#8b8b96' }
                }
              >
                {harmony.label}
              </span>
            ))}
          </div>
          <div className="flex gap-0.5 rounded-md bg-white/[0.04] p-0.5">
            {SECTIONS.map((section) => {
              const Icon = section.icon
              return (
                <span
                  key={section.id}
                  data-d={`sec sec-${section.id}`}
                  className="flex flex-1 items-center justify-center gap-0.5 rounded px-1 py-0.5 text-[7px]"
                  style={
                    section.id === 'inspect'
                      ? { backgroundColor: 'rgba(255,255,255,0.1)', color: '#f4f4f5' }
                      : { color: '#8b8b96' }
                  }
                >
                  <Icon className="size-2.5" /> {section.label}
                </span>
              )
            })}
          </div>
          <Views />
          <span className="pointer-events-none absolute inset-x-0 bottom-10 flex justify-center">
            <span
              data-d="space"
              className="rounded-lg border border-line-strong bg-surface px-4 py-1.5 font-mono text-[11px] text-ink opacity-0 shadow-2xl"
            >
              Space
            </span>
          </span>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
